1	package strategy
2	
3	import (
4		"bytes"
5		"context"
6		"errors"
7		"fmt"
8		"log/slog"
9		"os/exec"
10		"slices"
11		"strings"
12		"time"
13	
14		"github.com/go-git/go-git/v6"
15		"github.com/go-git/go-git/v6/plumbing"
16	
17		"github.com/entireio/cli/cmd/entire/cli/checkpoint"
18		"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
19		"github.com/entireio/cli/cmd/entire/cli/checkpoint/remote"
20		"github.com/entireio/cli/cmd/entire/cli/logging"
21		"github.com/entireio/cli/cmd/entire/cli/paths"
22		"github.com/entireio/cli/cmd/entire/cli/session"
23		"github.com/entireio/cli/cmd/entire/cli/settings"
24	)
25	
26	// ErrCheckpointDeleteNotFound means no local copy and no reachable remote
27	// holds the checkpoint.
28	var ErrCheckpointDeleteNotFound = errors.New("checkpoint not found")
29	
30	// ErrCheckpointDeleteV1WouldPropagate refuses a delete that would remove the
31	// local v1 copy while leaving the copy on the remote the next pre-push sends
32	// the v1 branch to: that push would carry the removal there anyway.
33	var ErrCheckpointDeleteV1WouldPropagate = errors.New("the local v1 removal would reach an unselected remote on the next push")
34	
35	// CheckpointRemoteTargetName names the dedicated checkpoint_remote store in
36	// delete plans and in --remote selection, which otherwise take git remote names.
37	const CheckpointRemoteTargetName = "checkpoint_remote"
38	
39	// checkpointDeleteProbeTimeout bounds each target's ls-remote during planning
40	// and re-checks. An unreachable target is reported, never fatal.
41	const checkpointDeleteProbeTimeout = 15 * time.Second
42	
43	// otherCheckpointScanLimit caps the same-session scan over local checkpoints.
44	const otherCheckpointScanLimit = 2000
45	
46	// v1BranchRef is the git-branch backend's shared checkpoint branch.
47	var v1BranchRef = plumbing.NewBranchReferenceName(paths.MetadataBranchName)
48	
49	// V1CopyState says whether a remote's v1 branch holds the checkpoint.
50	type V1CopyState string
51	
52	const (
53		V1CopyAbsent  V1CopyState = "absent"
54		V1CopyPresent V1CopyState = "present"
55		// V1CopyUnknown: the remote has a v1 branch whose tip is not in this
56		// clone, so its contents are verified only when the delete runs.
57		V1CopyUnknown V1CopyState = "unknown"
58	)
59	
60	// CheckpointDeleteTarget is one concrete place a checkpoint can be deleted
61	// from: a single URL or path, resolved up front so the probe, the lease and the
62	// push all address the same repository.
63	type CheckpointDeleteTarget struct {
64		// Remotes are the names that resolve to URL: git remote names, or
65		// CheckpointRemoteTargetName for the dedicated store.
66		Remotes []string
67		// URL is passed verbatim to git. Display it through Display only.
68		URL string
69		// Reachable is false when the probe failed (ProbeError says why) or was
70		// skipped (NotChecked).
71		Reachable  bool
72		ProbeError string
73		// NotChecked: --local-only planned the delete without contacting it.
74		NotChecked bool
75		// RefOID is the checkpoint ref's oid on the remote, zero when absent.
76		RefOID plumbing.Hash
77		// RefName is the checkpoint ref as the remote spells it (its shard's case
78		// can differ from a fresh computation).
79		RefName plumbing.ReferenceName
80		// V1Tip is the remote's v1 branch tip, zero when it has none.
81		V1Tip plumbing.Hash
82		V1    V1CopyState
83	}
84	
85	// Display returns the target's URL with credentials redacted.
86	func (t CheckpointDeleteTarget) Display() string { return remote.RedactURLOrPath(t.URL) }
87	
88	// Name returns the target's primary name for messages and retry commands.
89	func (t CheckpointDeleteTarget) Name() string {
90		if len(t.Remotes) == 0 {
91			return t.Display()
92		}
93		return t.Remotes[0]
94	}
95	
96	// HoldsCheckpoint reports whether the target has (or may have) a copy.
97	func (t CheckpointDeleteTarget) HoldsCheckpoint() bool {
98		return t.Reachable && (!t.RefOID.IsZero() || t.V1 == V1CopyPresent || t.V1 == V1CopyUnknown)
99	}
100	
101	// CheckpointDeleteSession is one session stored in the checkpoint, with the
102	// token delta the checkpoint carries for it.
103	type CheckpointDeleteSession struct {
104		SessionID    string
105		Agent        string
106		InputTokens  int
107		OutputTokens int
108	}
109	
110	// CheckpointDeleteState is a local session state that references the
111	// checkpoint and would otherwise write it again.
112	type CheckpointDeleteState struct {
113		SessionID string
114		// Active is true for a session that has not ended and whose agent may
115		// still be running.
116		Active bool
117		// Fields names the state fields that will be cleared.
118		Fields []string
119	}
120	
121	// CheckpointDeleteSibling is another local checkpoint that carries one of the
122	// deleted checkpoint's sessions.
123	type CheckpointDeleteSibling struct {
124		CheckpointID id.CheckpointID
125		SessionIDs   []string
126	}
127	
128	// CheckpointDeletePlan is everything a delete would touch, gathered without
129	// writing anything.
130	type CheckpointDeletePlan struct {
131		CheckpointID id.CheckpointID
132		// LocalRef is the local per-checkpoint ref ("" when absent).
133		LocalRef    plumbing.ReferenceName
134		LocalRefOID plumbing.Hash
135		// LocalV1 reports a copy on the local entire/checkpoints/v1 branch.
136		LocalV1 bool
137		// TrackingV1 lists remote names whose remote-tracking v1 ref holds it.
138		// Those refs move only when that remote's copy is deleted.
139		TrackingV1 []string
140		// V1PushURLs are where the next pre-push sends the local v1 branch: set
141		// only when git-branch is the primary backend and pushes are enabled.
142		V1PushURLs            []string
143		Targets               []CheckpointDeleteTarget
144		Sessions              []CheckpointDeleteSession
145		SessionStates         []CheckpointDeleteState
146		OtherLocalCheckpoints []CheckpointDeleteSibling
147		OtherLocalTruncated   bool
148		// PushSessionsDisabled reports push_sessions=false; the delete still
149		// reaches remotes when the user asks for it.
150		PushSessionsDisabled bool
151		Warnings             []string
152	}
153	
154	// HasLocalCopy reports whether this clone holds the checkpoint.
155	func (p *CheckpointDeletePlan) HasLocalCopy() bool {
156		return p.LocalRef != "" || p.LocalV1
157	}
158	
159	// HolderTargets returns the reachable targets that hold the checkpoint.
160	func (p *CheckpointDeletePlan) HolderTargets() []CheckpointDeleteTarget {
161		var out []CheckpointDeleteTarget
162		for _, t := range p.Targets {
163			if t.HoldsCheckpoint() {
164				out = append(out, t)
165			}
166		}
167		return out
168	}
169	
170	// ActiveStates returns the session states whose session is still running.
171	func (p *CheckpointDeletePlan) ActiveStates() []CheckpointDeleteState {
172		var out []CheckpointDeleteState
173		for _, s := range p.SessionStates {
174			if s.Active {
175				out = append(out, s)
176			}
177		}
178		return out
179	}
180	
181	// CheckpointDeletePlanOptions narrows what PlanCheckpointDelete inspects.
182	type CheckpointDeletePlanOptions struct {
183		// LocalOnly resolves the remote targets but never contacts them: each is
184		// marked NotChecked.
185		LocalOnly bool
186	}
187	
188	// UnreachableTargetNames names the targets the probe could not reach.
189	func (p *CheckpointDeletePlan) UnreachableTargetNames() []string {
190		var names []string
191		for _, t := range p.Targets {
192			if !t.Reachable && !t.NotChecked {
193				names = append(names, t.Name())
194			}
195		}
196		return names
197	}
198	
199	// CheckpointDeleteSelection says how the remote targets were chosen, so a
200	// refusal can name a remedy that works for that way of choosing.
201	type CheckpointDeleteSelection int
202	
203	const (
204		// SelectionAllHolders: every reachable holder (no narrowing).
205		SelectionAllHolders CheckpointDeleteSelection = iota
206		// SelectionLocalOnly: --local-only, no remote at all.
207		SelectionLocalOnly
208		// SelectionRemoteFlag: narrowed with --remote.
209		SelectionRemoteFlag
210		// SelectionPrompt: narrowed in the interactive remote picker.
211		SelectionPrompt
212	)
213	
214	// CheckLocalV1Propagation refuses a delete whose local v1 removal the next
215	// pre-push would carry to a remote the delete leaves alone. The removal is a
216	// commit on the local v1 branch, and pre-push fast-forwards each v1 push
217	// destination to it, deleting that destination's copy too. A destination
218	// probed and found without a v1 copy loses nothing; one that could not be
219	// probed is refused, since its copy cannot be ruled out.
220	//
221	// Known limitations: a push to a remote that is not yet the sync remote can
222	// elect it on the spot (capture) and send v1 there; such a remote is not a
223	// destination here until it is elected. A dedicated checkpoint_remote URL
224	// derived from a remote spelling this clone cannot authenticate to (another
225	// remote's protocol, say) probes as unreachable, so the delete keeps refusing
226	// with "retry when reachable" until that spelling works or the remote is
227	// removed.
228	func (p *CheckpointDeletePlan) CheckLocalV1Propagation(targets []CheckpointDeleteTarget, selection CheckpointDeleteSelection) error {
229		if !p.LocalV1 {
230			return nil
231		}
232		for _, url := range p.V1PushURLs {
233			if selection != SelectionLocalOnly && slices.ContainsFunc(targets, func(t CheckpointDeleteTarget) bool { return t.URL == url }) {
234				continue
235			}
236			dest := CheckpointDeleteTarget{URL: url}
237			if i := slices.IndexFunc(p.Targets, func(t CheckpointDeleteTarget) bool { return t.URL == url }); i >= 0 {
238				dest = p.Targets[i]
239			}
240			if dest.Reachable && dest.V1 == V1CopyAbsent {
241				continue
242			}
243			return p.v1PropagationError(dest, selection)
244		}
245		return nil
246	}
247	
248	func (p *CheckpointDeletePlan) v1PropagationError(dest CheckpointDeleteTarget, selection CheckpointDeleteSelection) error {
249		where := fmt.Sprintf("it is on the local %s branch, which the next git push sends to %s (%s)", paths.MetadataBranchName, dest.Name(), dest.Display())
250		if !dest.Reachable {
251			return fmt.Errorf("refusing to delete checkpoint %s: %w: %s, but %s could not be reached to check its copy; retry when %s is reachable",
252				p.CheckpointID, ErrCheckpointDeleteV1WouldPropagate, where, dest.Name(), dest.Name())
253		}
254		var remedy string
255		switch selection {
256		case SelectionLocalOnly:
257			remedy = "run without --local-only to delete that copy as well, or switch to the git-refs checkpoint backend"
258		case SelectionRemoteFlag:
259			remedy = "add --remote " + dest.Name() + " to delete that copy as well"
260		case SelectionPrompt:
261			remedy = "select " + dest.Name() + " too"
262		case SelectionAllHolders:
263			remedy = "delete it from " + dest.Name() + " as well"
264		}
265		return fmt.Errorf("refusing to delete checkpoint %s: %w: %s, removing that copy too; %s",
266			p.CheckpointID, ErrCheckpointDeleteV1WouldPropagate, where, remedy)
267	}
268	
269	// PlanCheckpointDelete inspects the local repository and every checkpoint
270	// remote for cid. It writes nothing: no fetch, no ref update, no state save.
271	func PlanCheckpointDelete(ctx context.Context, cid id.CheckpointID, opts CheckpointDeletePlanOptions) (*CheckpointDeletePlan, error) {
272		if cid.Kind() == id.KindUnknown {
273			return nil, fmt.Errorf("invalid checkpoint ID %q", cid)
274		}
275		root, err := paths.WorktreeRoot(ctx)
276		if err != nil {
277			return nil, fmt.Errorf("resolve worktree root: %w", err)
278		}
279		ctx = settings.WithWorktreeRoot(ctx, root)
280		repo, err := OpenRepository(ctx)
281		if err != nil {
282			return nil, err
283		}
284		defer repo.Close()
285	
286		plan := &CheckpointDeletePlan{CheckpointID: cid}
287		if s, loadErr := settings.Load(ctx); loadErr == nil {
288			plan.PushSessionsDisabled = s.IsPushSessionsDisabled()
289		}
290	
291		plan.LocalRef, plan.LocalRefOID, err = findLocalCheckpointRef(ctx, root, cid)
292		if err != nil {
293			return nil, err
294		}
295		// Any ID kind: a git-branch mirror writes ULID checkpoints to v1 too.
296		plan.LocalV1 = commitHasCheckpoint(repo, refTip(repo, v1BranchRef), cid)
297		plan.TrackingV1 = trackingV1Holders(ctx, repo, cid)
298	
299		targets := resolveDeleteTargets(ctx, root, plan)
300		if opts.LocalOnly {
301			// No remote is contacted, except a v1 push destination when this
302			// clone holds a v1 copy: CheckLocalV1Propagation needs to know
303			// whether the next push would remove a copy there.
304			var probe, skip []CheckpointDeleteTarget
305			for _, t := range targets {
306				if plan.LocalV1 && slices.Contains(plan.V1PushURLs, t.URL) {
307					probe = append(probe, t)
308					continue
309				}
310				t.NotChecked = true
311				skip = append(skip, t)
312			}
313			plan.Targets = append(probeDeleteTargets(ctx, root, repo, cid, probe), skip...)
314		} else {
315			plan.Targets = probeDeleteTargets(ctx, root, repo, cid, targets)
316		}
317		for _, t := range plan.Targets {
318			if !t.Reachable && !t.NotChecked {
319				plan.Warnings = append(plan.Warnings, fmt.Sprintf("could not reach %s (%s): %s", t.Name(), t.Display(), t.ProbeError))
320			}
321		}
322	
323		if !plan.HasLocalCopy() && len(plan.HolderTargets()) == 0 {
324			return plan, notFoundError(plan, opts.LocalOnly)
325		}
326	
327		readCheckpointSessions(ctx, repo, plan)
328		if err := collectDeleteStates(ctx, plan); err != nil {
329			return nil, err
330		}
331		collectOtherSessionCheckpoints(ctx, repo, plan)
332		return plan, nil
333	}
334	
335	// notFoundError says where the checkpoint was looked for, naming any remote
336	// that could not be checked, since one of those may still hold it.
337	func notFoundError(plan *CheckpointDeletePlan, localOnly bool) error {
338		if localOnly {
339			return fmt.Errorf("%w: %s is not in this repository (remotes were not checked: --local-only)", ErrCheckpointDeleteNotFound, plan.CheckpointID)
340		}
341		if unreachable := plan.UnreachableTargetNames(); len(unreachable) > 0 {
342			return fmt.Errorf("%w: %s is not in this repository or on any reachable checkpoint remote (could not reach %s)",
343				ErrCheckpointDeleteNotFound, plan.CheckpointID, strings.Join(unreachable, ", "))
344		}
345		return fmt.Errorf("%w: %s is not in this repository or on any reachable checkpoint remote", ErrCheckpointDeleteNotFound, plan.CheckpointID)
346	}
347	
348	// findLocalCheckpointRef lists refs/entire/checkpoints/*/<id> and matches with
349	// ParseRef, so a ref stored under a differently-cased shard is still found.
350	func findLocalCheckpointRef(ctx context.Context, root string, cid id.CheckpointID) (plumbing.ReferenceName, plumbing.Hash, error) {
351		cmd := exec.CommandContext(ctx, "git", "for-each-ref", "--format=%(objectname) %(refname)",
352			checkpoint.CheckpointRefPrefix+"*/"+cid.String())
353		cmd.Dir = root
354		out, err := cmd.Output()
355		if err != nil {
356			return "", plumbing.ZeroHash, fmt.Errorf("list local checkpoint refs: %w", err)
357		}
358		for line := range strings.SplitSeq(strings.TrimSpace(string(out)), "\n") {
359			oid, name, ok := strings.Cut(strings.TrimSpace(line), " ")
360			if !ok {
361				continue
362			}
363			ref := plumbing.ReferenceName(name)
364			if parsed, valid := checkpoint.ParseRef(ref); valid && parsed == cid {
365				return ref, plumbing.NewHash(oid), nil
366			}
367		}
368		return "", plumbing.ZeroHash, nil
369	}
370	
371	func refTip(repo *git.Repository, name plumbing.ReferenceName) plumbing.Hash {
372		ref, err := repo.Reference(name, true)
373		if err != nil {
374			return plumbing.ZeroHash
375		}
376		return ref.Hash()
377	}
378	
379	// commitHasCheckpoint reports whether the v1 commit's tree has cid's subtree.
380	// A commit not present in this clone reads as false.
381	func commitHasCheckpoint(repo *git.Repository, commitHash plumbing.Hash, cid id.CheckpointID) bool {
382		if commitHash.IsZero() {
383			return false
384		}
385		commit, err := repo.CommitObject(commitHash)
386		if err != nil {
387			return false
388		}
389		tree, err := commit.Tree()
390		if err != nil {
391			return false
392		}
393		_, err = tree.Tree(cid.Path())
394		return err == nil
395	}
396	
397	// trackingV1Holders lists remotes whose refs/remotes/<name>/entire/checkpoints/v1
398	// holds cid: reads fall back to these, so a delete must move them too.
399	func trackingV1Holders(ctx context.Context, repo *git.Repository, cid id.CheckpointID) []string {
400		var out []string
401		for _, name := range configuredRemoteNames(repo) {
402			tracking := plumbing.NewRemoteReferenceName(name, paths.MetadataBranchName)
403			if commitHasCheckpoint(repo, refTip(repo, tracking), cid) {
404				out = append(out, name)
405			}
406		}
407		logging.Debug(ctx, "checkpoint delete: tracking v1 holders", slog.Int("count", len(out)))
408		return out
409	}
410	
411	func configuredRemoteNames(repo *git.Repository) []string {
412		remotes, err := repo.Remotes()
413		if err != nil {
414			return nil
415		}
416		names := make([]string, 0, len(remotes))
417		for _, r := range remotes {
418			names = append(names, r.Config().Name)
419		}
420		slices.Sort(names)
421		return names
422	}
423	
424	// deleteTargetCandidate is a name → URL pair before deduplication.
425	type deleteTargetCandidate struct {
426		name string
427		url  string
428	}
429	
430	// resolveDeleteTargets resolves every place this clone's checkpoints can live
431	// to concrete URLs: the elected sync remote's push destination, the dedicated
432	// checkpoint_remote (push and fetch URLs), and each read candidate's fetch and
433	// first push URL (origin is the legacy tier). Names are resolved here, once,
434	// because git push would otherwise rewrite a name to the checkpoint_remote URL
435	// and token auth resolves names through the fetch URL.
436	func resolveDeleteTargets(ctx context.Context, root string, plan *CheckpointDeletePlan) []CheckpointDeleteTarget {
437		var candidates []deleteTargetCandidate
438		add := func(name, url string) {
439			if url != "" {
440				candidates = append(candidates, deleteTargetCandidate{name: name, url: url})
441			}
442		}
443		var v1Dests []string
444		addV1Dest := func(name, url string) {
445			add(name, url)
446			if url != "" && !slices.Contains(v1Dests, url) {
447				v1Dests = append(v1Dests, url)
448			}
449		}
450	
451		elected, electErr := ResolveCheckpointSyncRemote(ctx)
452		if electErr != nil {
453			plan.Warnings = append(plan.Warnings, "could not resolve the checkpoint sync remote: "+electErr.Error())
454		}
455		s, settingsErr := settings.Load(ctx)
456		checkpointRemoteConfigured := settingsErr == nil && s.GetCheckpointRemote() != nil
457		branchPrimary := !primaryIsGitRefs(ctx)
458	
459		// With a dedicated checkpoint_remote, pre-push derives its URL from
460		// whichever remote the user pushes to and bypasses the sync-remote gate,
461		// so every configured remote can send v1 there, elected or not.
462		electedUsesDedicated := false
463		if checkpointRemoteConfigured {
464			pushNames, _ := configuredRemotesInConfigOrderResult(ctx) //nolint:errcheck // an unreadable remote list adds no destinations
465			if elected.Name != "" && !slices.Contains(pushNames, elected.Name) {
466				pushNames = append([]string{elected.Name}, pushNames...)
467			}
468			for _, name := range pushNames {
469				if url, enabled, err := remote.PushURL(ctx, name); err == nil && enabled {
470					addV1Dest(CheckpointRemoteTargetName, url)
471					electedUsesDedicated = electedUsesDedicated || name == elected.Name
472				}
473			}
474			lead := LeadCheckpointReadRemote(ctx)
475			if dedicated, err := remote.ReadsDedicatedStore(ctx, lead); err == nil && dedicated {
476				if url, urlErr := remote.FetchURL(ctx, remote.FetchURLOptions{WorktreeRoot: root, LeadReadRemote: lead}); urlErr == nil {
477					add(CheckpointRemoteTargetName, url)
478				}
479			}
480		}
481	
482		names := []string{}
483		if elected.Name != "" {
484			names = append(names, elected.Name)
485		}
486		for _, c := range CheckpointReadRemotes(ctx) {
487			if !slices.Contains(names, c) {
488				names = append(names, c)
489			}
490		}
491		for _, name := range names {
492			if urls, err := remote.GetPushURLs(ctx, name); err == nil && len(urls) > 0 {
493				switch {
494				case name == elected.Name && branchPrimary && !electedUsesDedicated:
495					// git pushes the v1 branch to every pushurl of the sync remote.
496					for _, url := range urls {
497						addV1Dest(name, url)
498					}
499				default:
500					add(name, urls[0])
501				}
502			}
503			if url, err := remote.GetRemoteURL(ctx, name); err == nil {
504				add(name, url)
505			}
506		}
507		// pre-push sends the local v1 branch only on a git-branch primary, and
508		// not at all while push_sessions is disabled.
509		if branchPrimary && !plan.PushSessionsDisabled {
510			plan.V1PushURLs = v1Dests
511		}
512		return dedupeDeleteTargets(candidates)
513	}
514	
515	// dedupeDeleteTargets merges candidates that resolved to the same URL, keeping
516	// first-seen order of both URLs and names.
517	func dedupeDeleteTargets(candidates []deleteTargetCandidate) []CheckpointDeleteTarget {
518		var targets []CheckpointDeleteTarget
519		index := map[string]int{}
520		for _, c := range candidates {
521			i, seen := index[c.url]
522			if !seen {
523				index[c.url] = len(targets)
524				targets = append(targets, CheckpointDeleteTarget{URL: c.url, Remotes: []string{c.name}})
525				continue
526			}
527			if !slices.Contains(targets[i].Remotes, c.name) {
528				targets[i].Remotes = append(targets[i].Remotes, c.name)
529			}
530		}
531		return targets
532	}
533	
534	// probeDeleteTargets ls-remotes each target for the checkpoint ref and the v1
535	// branch. A failed probe marks the target unreachable.
536	func probeDeleteTargets(ctx context.Context, root string, repo *git.Repository, cid id.CheckpointID, targets []CheckpointDeleteTarget) []CheckpointDeleteTarget {
537		for i := range targets {
538			t := &targets[i]
539			listing, err := lsRemoteCheckpoint(ctx, root, t.URL, cid)
540			if err != nil {
541				t.ProbeError = err.Error()
542				continue
543			}
544			t.Reachable = true
545			t.RefName, t.RefOID = listing.ref, listing.refOID
546			t.V1Tip = listing.v1Tip
547			t.V1 = classifyRemoteV1(repo, cid, listing.v1Tip)
548		}
549		return targets
550	}
551	
552	func classifyRemoteV1(repo *git.Repository, cid id.CheckpointID, tip plumbing.Hash) V1CopyState {
553		switch {
554		case tip.IsZero():
555			return V1CopyAbsent
556		case commitHasCheckpoint(repo, tip, cid):
557			return V1CopyPresent
558		default:
559			if _, err := repo.CommitObject(tip); err == nil {
560				return V1CopyAbsent // the tip is local and has no such subtree
561			}
562			// Any ID kind: another clone, or this one under an earlier backend,
563			// can have pushed a ULID to the remote v1 branch, so its contents are
564			// checked when the delete runs.
565			return V1CopyUnknown
566		}
567	}
568	
569	type remoteCheckpointListing struct {
570		ref    plumbing.ReferenceName
571		refOID plumbing.Hash
572		v1Tip  plumbing.Hash
573	}
574	
575	// lsRemoteCheckpoint lists cid's ref and the v1 branch on target. The ref is
576	// matched by its id leaf (ls-remote patterns match a ref's tail) and confirmed
577	// with ParseRef, so a remote that stored it under a differently-cased shard is
578	// still found.
579	func lsRemoteCheckpoint(ctx context.Context, root, target string, cid id.CheckpointID) (remoteCheckpointListing, error) {
580		probeCtx, cancel := context.WithTimeout(ctx, checkpointDeleteProbeTimeout)
581		defer cancel()
582		out, err := remote.LsRemoteInDir(probeCtx, root, target, cid.String(), v1BranchRef.String())
583		if err != nil {
584			return remoteCheckpointListing{}, fmt.Errorf("ls-remote: %w", err)
585		}
586		return parseCheckpointLsRemote(out, cid), nil
587	}
588	
589	func parseCheckpointLsRemote(out []byte, cid id.CheckpointID) remoteCheckpointListing {
590		var listing remoteCheckpointListing
591		for line := range bytes.SplitSeq(out, []byte("\n")) {
592			fields := strings.Fields(string(line))
593			if len(fields) != 2 || !plumbing.IsHash(fields[0]) {
594				continue
595			}
596			name := plumbing.ReferenceName(fields[1])
597			if name == v1BranchRef {
598				listing.v1Tip = plumbing.NewHash(fields[0])
599				continue
600			}
601			if parsed, ok := checkpoint.ParseRef(name); ok && parsed == cid {
602				listing.ref, listing.refOID = name, plumbing.NewHash(fields[0])
603			}
604		}
605		return listing
606	}
