49	// V1CopyState says whether a remote's v1 branch holds the checkpoint.
50	type V1CopyState string
51	
52	const (
53		V1CopyAbsent  V1CopyState = "absent"
54		V1CopyPresent V1CopyState = "present"
55		// V1CopyUnknown: the remote has a v1 branch whose tip is not in this
56		// clone, so its contents are verified only when the delete runs.
57		V1CopyUnknown V1CopyState = "unknown"
