60	// CheckpointDeleteTarget is one concrete place a checkpoint can be deleted
61	// from: a single URL or path, resolved up front so the probe, the lease and the
62	// push all address the same repository.
63	type CheckpointDeleteTarget struct {
64		// Remotes are the names that resolve to URL: git remote names, or
65		// CheckpointRemoteTargetName for the dedicated store.
66		Remotes []string
67		// URL is passed verbatim to git. Display it through Display only.
68		URL string
69		// Reachable is false when the probe failed (ProbeError says why) or was
70		// skipped (NotChecked).
71		Reachable  bool
72		ProbeError string
73		// NotChecked: --local-only planned the delete without contacting it.
74		NotChecked bool
75		// RefOID is the checkpoint ref's oid on the remote, zero when absent.
76		RefOID plumbing.Hash
77		// RefName is the checkpoint ref as the remote spells it (its shard's case
78		// can differ from a fresh computation).
79		RefName plumbing.ReferenceName
80		// V1Tip is the remote's v1 branch tip, zero when it has none.
81		V1Tip plumbing.Hash
82		V1    V1CopyState
83	}
