96	// HoldsCheckpoint reports whether the target has (or may have) a copy.
97	func (t CheckpointDeleteTarget) HoldsCheckpoint() bool {
98		return t.Reachable && (!t.RefOID.IsZero() || t.V1 == V1CopyPresent || t.V1 == V1CopyUnknown)
