214	// CheckLocalV1Propagation refuses a delete whose local v1 removal the next
215	// pre-push would carry to a remote the delete leaves alone. The removal is a
216	// commit on the local v1 branch, and pre-push fast-forwards each v1 push
217	// destination to it, deleting that destination's copy too. A destination
218	// probed and found without a v1 copy loses nothing; one that could not be
219	// probed is refused, since its copy cannot be ruled out.
220	//
221	// Known limitations: a push to a remote that is not yet the sync remote can
222	// elect it on the spot (capture) and send v1 there; such a remote is not a
223	// destination here until it is elected. A dedicated checkpoint_remote URL
224	// derived from a remote spelling this clone cannot authenticate to (another
225	// remote's protocol, say) probes as unreachable, so the delete keeps refusing
226	// with "retry when reachable" until that spelling works or the remote is
227	// removed.
228	func (p *CheckpointDeletePlan) CheckLocalV1Propagation(targets []CheckpointDeleteTarget, selection CheckpointDeleteSelection) error {
229		if !p.LocalV1 {
230			return nil
231		}
232		for _, url := range p.V1PushURLs {
233			if selection != SelectionLocalOnly && slices.ContainsFunc(targets, func(t CheckpointDeleteTarget) bool { return t.URL == url }) {
234				continue
235			}
236			dest := CheckpointDeleteTarget{URL: url}
237			if i := slices.IndexFunc(p.Targets, func(t CheckpointDeleteTarget) bool { return t.URL == url }); i >= 0 {
238				dest = p.Targets[i]
239			}
240			if dest.Reachable && dest.V1 == V1CopyAbsent {
241				continue
242			}
243			return p.v1PropagationError(dest, selection)
244		}
245		return nil
246	}
247	
248	func (p *CheckpointDeletePlan) v1PropagationError(dest CheckpointDeleteTarget, selection CheckpointDeleteSelection) error {
249		where := fmt.Sprintf("it is on the local %s branch, which the next git push sends to %s (%s)", paths.MetadataBranchName, dest.Name(), dest.Display())
250		if !dest.Reachable {
251			return fmt.Errorf("refusing to delete checkpoint %s: %w: %s, but %s could not be reached to check its copy; retry when %s is reachable",
252				p.CheckpointID, ErrCheckpointDeleteV1WouldPropagate, where, dest.Name(), dest.Name())
253		}
254		var remedy string
255		switch selection {
256		case SelectionLocalOnly:
257			remedy = "run without --local-only to delete that copy as well, or switch to the git-refs checkpoint backend"
258		case SelectionRemoteFlag:
259			remedy = "add --remote " + dest.Name() + " to delete that copy as well"
260		case SelectionPrompt:
261			remedy = "select " + dest.Name() + " too"
262		case SelectionAllHolders:
263			remedy = "delete it from " + dest.Name() + " as well"
264		}
265		return fmt.Errorf("refusing to delete checkpoint %s: %w: %s, removing that copy too; %s",
266			p.CheckpointID, ErrCheckpointDeleteV1WouldPropagate, where, remedy)
267	}
