644	// collectDeleteStates finds the session states that reference cid. Read-only:
645	// it lists without the orphan cleanup the hook-path listing performs.
646	func collectDeleteStates(ctx context.Context, plan *CheckpointDeletePlan) error {
647		store, err := session.NewStateStore(ctx)
648		if err != nil {
649			return fmt.Errorf("open session state store: %w", err)
650		}
651		states, err := store.ListReadOnly(ctx)
652		if err != nil {
653			return fmt.Errorf("list session states: %w", err)
654		}
655		for _, st := range states {
656			fields := deleteStateFields(st, plan.CheckpointID)
657			if len(fields) == 0 {
658				continue
659			}
660			plan.SessionStates = append(plan.SessionStates, CheckpointDeleteState{
661				SessionID: st.SessionID,
662				Active:    !st.IsEnded() && !st.OwnerExited(),
663				Fields:    fields,
664			})
665		}
666		return nil
667	}
668	
669	// deleteStateFields names the fields of st that hold cid. These are the only
670	// fields a delete clears: token offsets, usage and baselines are never touched,
671	// since resetting any of them would make the next checkpoint re-count tokens
672	// already stored in surviving checkpoints.
673	func deleteStateFields(st *SessionState, cid id.CheckpointID) []string {
674		var fields []string
675		if st.LastCheckpointID == cid {
676			fields = append(fields, "last_checkpoint_id")
677		}
678		if st.PendingCondensationID() == cid {
679			fields = append(fields, "condensation_attempt")
680		}
681		if slices.Contains(st.TurnCheckpointIDs, cid.String()) {
682			fields = append(fields, "turn_checkpoint_ids")
683		}
684		return fields
685	}
686	
687	// clearDeletedCheckpointFromState removes cid from st, reporting whether
688	// anything changed.
689	func clearDeletedCheckpointFromState(st *SessionState, cid id.CheckpointID) bool {
690		changed := false
691		if st.LastCheckpointID == cid {
692			st.LastCheckpointID = id.EmptyCheckpointID
693			changed = true
694		}
695		if st.PendingCondensationID() == cid {
696			st.ClearCondensationAttempt()
697			changed = true
698		}
699		if i := slices.Index(st.TurnCheckpointIDs, cid.String()); i >= 0 {
700			st.TurnCheckpointIDs = slices.DeleteFunc(st.TurnCheckpointIDs, func(s string) bool { return s == cid.String() })
701			changed = true
702		}
703		return changed
704	}
705	
706	// collectOtherSessionCheckpoints lists other local checkpoints that carry one
707	// of the deleted checkpoint's sessions. Local only, and capped: phase 1 warns
708	// about them, it never deletes them.
709	func collectOtherSessionCheckpoints(ctx context.Context, repo *git.Repository, plan *CheckpointDeletePlan) {
710		if len(plan.Sessions) == 0 {
711			return
712		}
713		wanted := make(map[string]bool, len(plan.Sessions))
714		for _, s := range plan.Sessions {
715			wanted[s.SessionID] = true
716		}
717		store, err := openLocalOnlyStore(ctx, repo)
718		if err != nil {
719			return
720		}
721		infos, err := store.List(ctx)
722		if err != nil {
723			plan.Warnings = append(plan.Warnings, "could not scan local checkpoints for the same sessions: "+err.Error())
724			return
725		}
726		if len(infos) > otherCheckpointScanLimit {
727			infos = infos[:otherCheckpointScanLimit]
728			plan.OtherLocalTruncated = true
729		}
730		for _, info := range infos {
731			if info.CheckpointID == plan.CheckpointID {
732				continue
733			}
734			var shared []string
735			for _, sid := range sessionIDsOf(info) {
736				if wanted[sid] && !slices.Contains(shared, sid) {
737					shared = append(shared, sid)
738				}
739			}
740			if len(shared) > 0 {
741				plan.OtherLocalCheckpoints = append(plan.OtherLocalCheckpoints, CheckpointDeleteSibling{CheckpointID: info.CheckpointID, SessionIDs: shared})
742			}
743		}
744	}
745	
746	func sessionIDsOf(info checkpoint.CheckpointInfo) []string {
747		if len(info.SessionIDs) > 0 {
748			return info.SessionIDs
749		}
750		if info.SessionID != "" {
751			return []string{info.SessionID}
752		}
753		return nil
754	}
