181	// CheckpointDeletePlanOptions narrows what PlanCheckpointDelete inspects.
182	type CheckpointDeletePlanOptions struct {
183		// LocalOnly resolves the remote targets but never contacts them: each is
184		// marked NotChecked.
185		LocalOnly bool
186	}
