188	// UnreachableTargetNames names the targets the probe could not reach.
189	func (p *CheckpointDeletePlan) UnreachableTargetNames() []string {
190		var names []string
191		for _, t := range p.Targets {
192			if !t.Reachable && !t.NotChecked {
193				names = append(names, t.Name())
194			}
195		}
196		return names
197	}
