269	// PlanCheckpointDelete inspects the local repository and every checkpoint
270	// remote for cid. It writes nothing: no fetch, no ref update, no state save.
271	func PlanCheckpointDelete(ctx context.Context, cid id.CheckpointID, opts CheckpointDeletePlanOptions) (*CheckpointDeletePlan, error) {
272		if cid.Kind() == id.KindUnknown {
273			return nil, fmt.Errorf("invalid checkpoint ID %q", cid)
274		}
275		root, err := paths.WorktreeRoot(ctx)
276		if err != nil {
277			return nil, fmt.Errorf("resolve worktree root: %w", err)
278		}
279		ctx = settings.WithWorktreeRoot(ctx, root)
280		repo, err := OpenRepository(ctx)
281		if err != nil {
282			return nil, err
283		}
284		defer repo.Close()
285	
286		plan := &CheckpointDeletePlan{CheckpointID: cid}
287		if s, loadErr := settings.Load(ctx); loadErr == nil {
288			plan.PushSessionsDisabled = s.IsPushSessionsDisabled()
289		}
290	
291		plan.LocalRef, plan.LocalRefOID, err = findLocalCheckpointRef(ctx, root, cid)
292		if err != nil {
293			return nil, err
294		}
295		// Any ID kind: a git-branch mirror writes ULID checkpoints to v1 too.
296		plan.LocalV1 = commitHasCheckpoint(repo, refTip(repo, v1BranchRef), cid)
297		plan.TrackingV1 = trackingV1Holders(ctx, repo, cid)
298	
299		targets := resolveDeleteTargets(ctx, root, plan)
300		if opts.LocalOnly {
301			// No remote is contacted, except a v1 push destination when this
302			// clone holds a v1 copy: CheckLocalV1Propagation needs to know
303			// whether the next push would remove a copy there.
304			var probe, skip []CheckpointDeleteTarget
305			for _, t := range targets {
306				if plan.LocalV1 && slices.Contains(plan.V1PushURLs, t.URL) {
307					probe = append(probe, t)
308					continue
309				}
310				t.NotChecked = true
311				skip = append(skip, t)
312			}
313			plan.Targets = append(probeDeleteTargets(ctx, root, repo, cid, probe), skip...)
314		} else {
315			plan.Targets = probeDeleteTargets(ctx, root, repo, cid, targets)
316		}
317		for _, t := range plan.Targets {
318			if !t.Reachable && !t.NotChecked {
319				plan.Warnings = append(plan.Warnings, fmt.Sprintf("could not reach %s (%s): %s", t.Name(), t.Display(), t.ProbeError))
320			}
321		}
322	
323		if !plan.HasLocalCopy() && len(plan.HolderTargets()) == 0 {
324			return plan, notFoundError(plan, opts.LocalOnly)
325		}
326	
327		readCheckpointSessions(ctx, repo, plan)
328		if err := collectDeleteStates(ctx, plan); err != nil {
329			return nil, err
330		}
331		collectOtherSessionCheckpoints(ctx, repo, plan)
332		return plan, nil
333	}
334	
335	// notFoundError says where the checkpoint was looked for, naming any remote
336	// that could not be checked, since one of those may still hold it.
337	func notFoundError(plan *CheckpointDeletePlan, localOnly bool) error {
338		if localOnly {
339			return fmt.Errorf("%w: %s is not in this repository (remotes were not checked: --local-only)", ErrCheckpointDeleteNotFound, plan.CheckpointID)
340		}
341		if unreachable := plan.UnreachableTargetNames(); len(unreachable) > 0 {
342			return fmt.Errorf("%w: %s is not in this repository or on any reachable checkpoint remote (could not reach %s)",
343				ErrCheckpointDeleteNotFound, plan.CheckpointID, strings.Join(unreachable, ", "))
344		}
345		return fmt.Errorf("%w: %s is not in this repository or on any reachable checkpoint remote", ErrCheckpointDeleteNotFound, plan.CheckpointID)
346	}
