348	// findLocalCheckpointRef lists refs/entire/checkpoints/*/<id> and matches with
349	// ParseRef, so a ref stored under a differently-cased shard is still found.
350	func findLocalCheckpointRef(ctx context.Context, root string, cid id.CheckpointID) (plumbing.ReferenceName, plumbing.Hash, error) {
351		cmd := exec.CommandContext(ctx, "git", "for-each-ref", "--format=%(objectname) %(refname)",
352			checkpoint.CheckpointRefPrefix+"*/"+cid.String())
353		cmd.Dir = root
354		out, err := cmd.Output()
355		if err != nil {
356			return "", plumbing.ZeroHash, fmt.Errorf("list local checkpoint refs: %w", err)
357		}
358		for line := range strings.SplitSeq(strings.TrimSpace(string(out)), "\n") {
359			oid, name, ok := strings.Cut(strings.TrimSpace(line), " ")
360			if !ok {
361				continue
362			}
363			ref := plumbing.ReferenceName(name)
364			if parsed, valid := checkpoint.ParseRef(ref); valid && parsed == cid {
365				return ref, plumbing.NewHash(oid), nil
366			}
367		}
368		return "", plumbing.ZeroHash, nil
369	}
370	
371	func refTip(repo *git.Repository, name plumbing.ReferenceName) plumbing.Hash {
372		ref, err := repo.Reference(name, true)
373		if err != nil {
374			return plumbing.ZeroHash
375		}
376		return ref.Hash()
377	}
