397	// trackingV1Holders lists remotes whose refs/remotes/<name>/entire/checkpoints/v1
398	// holds cid: reads fall back to these, so a delete must move them too.
399	func trackingV1Holders(ctx context.Context, repo *git.Repository, cid id.CheckpointID) []string {
400		var out []string
401		for _, name := range configuredRemoteNames(repo) {
402			tracking := plumbing.NewRemoteReferenceName(name, paths.MetadataBranchName)
403			if commitHasCheckpoint(repo, refTip(repo, tracking), cid) {
404				out = append(out, name)
405			}
406		}
407		logging.Debug(ctx, "checkpoint delete: tracking v1 holders", slog.Int("count", len(out)))
408		return out
409	}
410	
411	func configuredRemoteNames(repo *git.Repository) []string {
412		remotes, err := repo.Remotes()
413		if err != nil {
414			return nil
415		}
416		names := make([]string, 0, len(remotes))
417		for _, r := range remotes {
418			names = append(names, r.Config().Name)
419		}
420		slices.Sort(names)
421		return names
422	}
423	
424	// deleteTargetCandidate is a name → URL pair before deduplication.
425	type deleteTargetCandidate struct {
426		name string
427		url  string
428	}
429	
430	// resolveDeleteTargets resolves every place this clone's checkpoints can live
431	// to concrete URLs: the elected sync remote's push destination, the dedicated
432	// checkpoint_remote (push and fetch URLs), and each read candidate's fetch and
433	// first push URL (origin is the legacy tier). Names are resolved here, once,
434	// because git push would otherwise rewrite a name to the checkpoint_remote URL
435	// and token auth resolves names through the fetch URL.
436	func resolveDeleteTargets(ctx context.Context, root string, plan *CheckpointDeletePlan) []CheckpointDeleteTarget {
437		var candidates []deleteTargetCandidate
438		add := func(name, url string) {
439			if url != "" {
440				candidates = append(candidates, deleteTargetCandidate{name: name, url: url})
441			}
442		}
443		var v1Dests []string
444		addV1Dest := func(name, url string) {
445			add(name, url)
446			if url != "" && !slices.Contains(v1Dests, url) {
447				v1Dests = append(v1Dests, url)
448			}
449		}
450	
451		elected, electErr := ResolveCheckpointSyncRemote(ctx)
452		if electErr != nil {
453			plan.Warnings = append(plan.Warnings, "could not resolve the checkpoint sync remote: "+electErr.Error())
454		}
455		s, settingsErr := settings.Load(ctx)
456		checkpointRemoteConfigured := settingsErr == nil && s.GetCheckpointRemote() != nil
457		branchPrimary := !primaryIsGitRefs(ctx)
458	
459		// With a dedicated checkpoint_remote, pre-push derives its URL from
460		// whichever remote the user pushes to and bypasses the sync-remote gate,
461		// so every configured remote can send v1 there, elected or not.
462		electedUsesDedicated := false
463		if checkpointRemoteConfigured {
464			pushNames, _ := configuredRemotesInConfigOrderResult(ctx) //nolint:errcheck // an unreadable remote list adds no destinations
465			if elected.Name != "" && !slices.Contains(pushNames, elected.Name) {
466				pushNames = append([]string{elected.Name}, pushNames...)
467			}
468			for _, name := range pushNames {
469				if url, enabled, err := remote.PushURL(ctx, name); err == nil && enabled {
470					addV1Dest(CheckpointRemoteTargetName, url)
471					electedUsesDedicated = electedUsesDedicated || name == elected.Name
472				}
473			}
474			lead := LeadCheckpointReadRemote(ctx)
475			if dedicated, err := remote.ReadsDedicatedStore(ctx, lead); err == nil && dedicated {
476				if url, urlErr := remote.FetchURL(ctx, remote.FetchURLOptions{WorktreeRoot: root, LeadReadRemote: lead}); urlErr == nil {
477					add(CheckpointRemoteTargetName, url)
478				}
479			}
480		}
481	
482		names := []string{}
483		if elected.Name != "" {
484			names = append(names, elected.Name)
485		}
486		for _, c := range CheckpointReadRemotes(ctx) {
487			if !slices.Contains(names, c) {
488				names = append(names, c)
489			}
490		}
491		for _, name := range names {
492			if urls, err := remote.GetPushURLs(ctx, name); err == nil && len(urls) > 0 {
493				switch {
494				case name == elected.Name && branchPrimary && !electedUsesDedicated:
495					// git pushes the v1 branch to every pushurl of the sync remote.
496					for _, url := range urls {
497						addV1Dest(name, url)
498					}
499				default:
500					add(name, urls[0])
501				}
502			}
503			if url, err := remote.GetRemoteURL(ctx, name); err == nil {
504				add(name, url)
505			}
506		}
507		// pre-push sends the local v1 branch only on a git-branch primary, and
508		// not at all while push_sessions is disabled.
509		if branchPrimary && !plan.PushSessionsDisabled {
510			plan.V1PushURLs = v1Dests
511		}
512		return dedupeDeleteTargets(candidates)
513	}
514	
515	// dedupeDeleteTargets merges candidates that resolved to the same URL, keeping
516	// first-seen order of both URLs and names.
517	func dedupeDeleteTargets(candidates []deleteTargetCandidate) []CheckpointDeleteTarget {
518		var targets []CheckpointDeleteTarget
519		index := map[string]int{}
520		for _, c := range candidates {
521			i, seen := index[c.url]
522			if !seen {
523				index[c.url] = len(targets)
524				targets = append(targets, CheckpointDeleteTarget{URL: c.url, Remotes: []string{c.name}})
525				continue
526			}
527			if !slices.Contains(targets[i].Remotes, c.name) {
528				targets[i].Remotes = append(targets[i].Remotes, c.name)
529			}
530		}
531		return targets
532	}
533	
534	// probeDeleteTargets ls-remotes each target for the checkpoint ref and the v1
535	// branch. A failed probe marks the target unreachable.
536	func probeDeleteTargets(ctx context.Context, root string, repo *git.Repository, cid id.CheckpointID, targets []CheckpointDeleteTarget) []CheckpointDeleteTarget {
537		for i := range targets {
538			t := &targets[i]
539			listing, err := lsRemoteCheckpoint(ctx, root, t.URL, cid)
540			if err != nil {
541				t.ProbeError = err.Error()
542				continue
543			}
544			t.Reachable = true
545			t.RefName, t.RefOID = listing.ref, listing.refOID
546			t.V1Tip = listing.v1Tip
547			t.V1 = classifyRemoteV1(repo, cid, listing.v1Tip)
548		}
549		return targets
550	}
551	
552	func classifyRemoteV1(repo *git.Repository, cid id.CheckpointID, tip plumbing.Hash) V1CopyState {
553		switch {
554		case tip.IsZero():
555			return V1CopyAbsent
556		case commitHasCheckpoint(repo, tip, cid):
557			return V1CopyPresent
558		default:
559			if _, err := repo.CommitObject(tip); err == nil {
560				return V1CopyAbsent // the tip is local and has no such subtree
561			}
562			// Any ID kind: another clone, or this one under an earlier backend,
563			// can have pushed a ULID to the remote v1 branch, so its contents are
564			// checked when the delete runs.
565			return V1CopyUnknown
566		}
567	}
568	
569	type remoteCheckpointListing struct {
570		ref    plumbing.ReferenceName
571		refOID plumbing.Hash
572		v1Tip  plumbing.Hash
573	}
574	
575	// lsRemoteCheckpoint lists cid's ref and the v1 branch on target. The ref is
576	// matched by its id leaf (ls-remote patterns match a ref's tail) and confirmed
577	// with ParseRef, so a remote that stored it under a differently-cased shard is
578	// still found.
579	func lsRemoteCheckpoint(ctx context.Context, root, target string, cid id.CheckpointID) (remoteCheckpointListing, error) {
580		probeCtx, cancel := context.WithTimeout(ctx, checkpointDeleteProbeTimeout)
581		defer cancel()
582		out, err := remote.LsRemoteInDir(probeCtx, root, target, cid.String(), v1BranchRef.String())
583		if err != nil {
584			return remoteCheckpointListing{}, fmt.Errorf("ls-remote: %w", err)
585		}
586		return parseCheckpointLsRemote(out, cid), nil
587	}
588	
589	func parseCheckpointLsRemote(out []byte, cid id.CheckpointID) remoteCheckpointListing {
590		var listing remoteCheckpointListing
591		for line := range bytes.SplitSeq(out, []byte("\n")) {
592			fields := strings.Fields(string(line))
593			if len(fields) != 2 || !plumbing.IsHash(fields[0]) {
594				continue
595			}
596			name := plumbing.ReferenceName(fields[1])
597			if name == v1BranchRef {
598				listing.v1Tip = plumbing.NewHash(fields[0])
599				continue
600			}
601			if parsed, ok := checkpoint.ParseRef(name); ok && parsed == cid {
602				listing.ref, listing.refOID = name, plumbing.NewHash(fields[0])
603			}
604		}
605		return listing
606	}
