37	// CheckpointDeleteOptions selects what ExecuteCheckpointDelete touches.
38	type CheckpointDeleteOptions struct {
39		// Targets are the remote targets to delete from (a subset of the plan's).
40		Targets []CheckpointDeleteTarget
41		// LocalOnly skips every remote.
42		LocalOnly bool
43		// Selection says how Targets were chosen; it only shapes the wording of
44		// a refusal. LocalOnly implies SelectionLocalOnly.
