55	// CheckpointDeleteTargetResult is the outcome on one remote target.
56	type CheckpointDeleteTargetResult struct {
57		Target CheckpointDeleteTarget
58		Ref    DeleteOutcome
59		V1     DeleteOutcome
60		Error  string
61	}
62	
63	// Failed reports whether anything on this target failed.
64	func (r CheckpointDeleteTargetResult) Failed() bool {
65		return r.Ref == DeleteOutcomeFailed || r.V1 == DeleteOutcomeFailed
66	}
67	
68	// CheckpointDeleteResult reports every step of a delete.
69	type CheckpointDeleteResult struct {
70		StatesCleared []string
71		LocalRef      DeleteOutcome
72		LocalV1       DeleteOutcome
73		Targets       []CheckpointDeleteTargetResult
74	}
75	
76	// Failed reports whether any requested remote delete failed.
77	func (r *CheckpointDeleteResult) Failed() bool {
78		for _, t := range r.Targets {
79			if t.Failed() {
80				return true
81			}
82		}
83		return false
84	}
