86	// errNothingToRemove stops a v1 rebuild whose tree no longer has the subtree.
87	var errNothingToRemove = errors.New("checkpoint subtree already absent")
88	
89	// ExecuteCheckpointDelete deletes the planned checkpoint.
90	//
91	// Order matters. Session states are cleared first so no local writer (an
92	// amend restoring the trailer, a pending condensation) recreates the ID, and
93	// the ID is recorded on the deleted list before any ref goes. The local ref is
94	// then removed before any remote one: a concurrent pre-push drains the queue
95	// and pushes refs that exist locally, so deleting remote-first would let it
96	// push the ref back between the two deletes. Remote failures are reported per
97	// target and never restore the local copy; the user retries with --remote.
98	func ExecuteCheckpointDelete(ctx context.Context, plan *CheckpointDeletePlan, opts CheckpointDeleteOptions) (_ *CheckpointDeleteResult, retErr error) {
99		if err := plan.CheckLocalV1Propagation(opts.Targets, opts.selection()); err != nil {
100			return nil, err
101		}
102		root, err := paths.WorktreeRoot(ctx)
103		if err != nil {
104			return nil, fmt.Errorf("resolve worktree root: %w", err)
105		}
106		ctx = settings.WithWorktreeRoot(ctx, root)
107		cid := plan.CheckpointID
108		result := &CheckpointDeleteResult{LocalRef: DeleteOutcomeAbsent, LocalV1: DeleteOutcomeAbsent}
109	
110		repo, err := OpenRepository(ctx)
111		if err != nil {
112			return result, err
113		}
114		defer repo.Close()
115	
116		// Recorded first, so a hook racing the steps below (an amend, a
117		// migration) already declines the ID.
118		deletedList, err := checkpoint.DeletedCheckpointsForRepo(repo)
119		if err != nil {
120			return result, fmt.Errorf("record deleted checkpoint: %w", err)
121		}
122		addedHere, err := deletedList.Add(cid)
123		if err != nil {
124			return result, fmt.Errorf("record deleted checkpoint: %w", err)
125		}
126		// A delete that removed no copy (it failed early, or every remote
127		// refused) must not leave the ID listed: hooks would strip the trailer of
128		// a checkpoint that still exists. Only this run's own record is undone; an
129		// ID an earlier, partly successful delete recorded stays.
130		copyDeleted := false
131		defer func() {
132			if !addedHere || copyDeleted || result.anyRemoteDeleted() || !failuresLeftEveryCopy(ctx, root, cid, result) {
133				return
134			}
135			if err := deletedList.Remove(cid); err != nil {
136				logging.Warn(ctx, "checkpoint delete: could not unrecord a delete that removed nothing",
137					slog.String("checkpoint_id", cid.String()), slog.String("error", err.Error()))
138			}
139		}()
140	
141		for _, sessionID := range sessionsHoldingCheckpoint(ctx, plan) {
142			changed := false
143			if err := MutateSessionState(ctx, sessionID, func(state *SessionState) error {
144				if !clearDeletedCheckpointFromState(state, cid) {
145					return ErrMutationSkip
146				}
147				changed = true
148				return nil
149			}); err != nil && !errors.Is(err, ErrStateNotFound) {
150				return result, fmt.Errorf("clear checkpoint from session %s: %w", sessionID, err)
151			}
152			if changed {
153				result.StatesCleared = append(result.StatesCleared, sessionID)
154			}
155		}
156	
157		refDeleted, err := deleteLocalCheckpointRef(ctx, root, repo, plan)
158		copyDeleted = refDeleted
159		if refDeleted {
160			result.LocalRef = DeleteOutcomeDeleted
161		}
162		if err != nil {
163			result.LocalRef = DeleteOutcomeFailed
164			return result, err
165		}
166	
167		var localRemoval plumbing.Hash
168		if plan.LocalV1 {
169			removal, removed, err := removeLocalV1Checkpoint(ctx, repo, cid)
170			localRemoval = removal
171			if err != nil {
172				result.LocalV1 = DeleteOutcomeFailed
173				return result, fmt.Errorf("remove checkpoint from local %s: %w", paths.MetadataBranchName, err)
174			}
175			if removed {
176				result.LocalV1 = DeleteOutcomeDeleted
177				copyDeleted = true
178			}
179		}
180	
181		if opts.LocalOnly {
182			return result, nil
183		}
184		adopted := false
185		for _, target := range opts.Targets {
186			res, pushedV1 := deleteFromTarget(ctx, root, cid, target)
187			result.Targets = append(result.Targets, res)
188			if !adopted && !pushedV1.IsZero() && !localRemoval.IsZero() && slices.Contains(plan.V1PushURLs, target.URL) {
189				adopted = true
190				if err := adoptRemoteV1Removal(ctx, repo, cid, refTip(repo, v1BranchRef), localRemoval, pushedV1); err != nil {
191					logging.Warn(ctx, "checkpoint delete: local v1 left as is; the next push reconciles it (with OPF on, it refuses until v1 is recovered)",
192						slog.String("checkpoint_id", cid.String()), slog.String("reason", err.Error()))
193				}
194			}
195		}
196		recheckRemoteRefs(ctx, root, cid, result)
197		return result, nil
198	}
